<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useLocale } from 'vuetify';
import { VMenu } from 'vuetify/components/VMenu';
import { VCard } from 'vuetify/components/VCard';
import { AuColorField, AuSvgViewport, AuSwitch, AuRoot, AuLayout, AuButton, AuIcon, AuCard, AuHelp, AuNumericField, AuSelect, AuCheckbox, AuSlider, AuTabs, AuAlert, AuProgress, AuSwatches, AuExampleCard, AuSegmentedControl, AuPanelHeader, AuFieldNote, adjustNumericDraft } from '@timotf/atomm-ui';
const locale = ref<'fr'|'en'>('fr'), direction = ref<'ltr'|'rtl'>('ltr'), tab = ref('preview');
const mirrored = ref(false), viewport = ref<InstanceType<typeof AuSvgViewport>>();
const settingsOpen = ref(false), exampleLayout = ref<'tile'|'row'>('tile');
const number = ref('0,25'), material = ref('paper'), enabled = ref(true), slider = ref(35), color = ref('#c44336'), saved = ref(false), cancelled = ref(false), sample = ref('A');
const scrub = ref('6,05'), integer = ref('6'), readOnlyDraft = ref('4'), disabledDraft = ref('5'), noDragDraft = ref('3'), showScrub = ref(true), density = ref('spacing');
const uiLocale = useLocale();
const text = (fr: string,en: string) => locale.value === 'fr' ? fr : en;
watch(locale,value => { document.documentElement.lang = value; uiLocale.current.value = value; });
const numericError = computed(() => (locale.value === 'fr' ? /^[+-]?(?:\d+(?:,\d+)?|,\d+)$/ : /^[+-]?(?:\d+(?:\.\d+)?|\.\d+)$/).test(number.value) ? undefined : text('Saisissez une décimale valide.','Enter a valid decimal.'));
function adjust(value: string,delta: number) {
  if (!(locale.value === 'fr' ? /^[+-]?(?:\d+(?:,\d+)?|,\d+)$/ : /^[+-]?(?:\d+(?:\.\d+)?|\.\d+)$/).test(value)) return null;
  return adjustNumericDraft(value,delta,{decimalSeparator:locale.value === 'fr' ? ',' : '.'});
}
function changeLocale(value: string) {
  if (value !== 'fr' && value !== 'en') return;
  if (!numericError.value) number.value = number.value.replace(value === 'fr' ? '.' : ',',value === 'fr' ? ',' : '.');
  locale.value = value;
}
</script>
<template>
  <AuRoot :direction="direction" profile="compact" class="gallery-app"><AuLayout :lead-label="text('Catalogue','Catalogue')" :stage-label="text('Démonstration','Demonstration')" :parameters-label="text('Composants','Components')">
    <template #lead><AuPanelHeader class="gallery-header"><span>AtommUI</span><small>0.4.1</small></AuPanelHeader><div class="gallery-rail-content"><div class="gallery-intro"><span class="gallery-eyebrow">VUE · VUETIFY · TYPESCRIPT</span><h1>{{ text('Les mêmes repères, dans chaque générateur.','Familiar controls in every generator.') }}</h1><p>{{ text('Une bibliothèque de composants sobres, réutilisables et adaptés aux panneaux atomm.','A library of refined, reusable controls for atomm panels.') }}</p></div><AuSegmentedControl id="gallery-example-layout" v-model="exampleLayout" :label="text('Présentation des exemples','Example layout')" :items="[{value:'tile',title:text('Carte','Tile')},{value:'row',title:text('Ligne','Row')}]" /><div class="gallery-examples"><AuExampleCard v-for="option in ['A','B','C']" :key="option" :title="option" :layout="exampleLayout" :data-testid="`gallery-example-${option}`" :active="sample === option" @click="sample = option"><svg viewBox="0 0 48 48" fill="currentColor"><circle v-if="option === 'A'" cx="24" cy="24" r="16"/><rect v-else-if="option === 'B'" x="8" y="8" width="32" height="32" rx="4"/><path v-else d="m24 5 20 36H4Z"/></svg></AuExampleCard></div><AuSelect id="gallery-language" :label="text('Langue','Language')" :model-value="locale" :items="[{value:'fr',title:'Français'},{value:'en',title:'English'}]" @update:model-value="changeLocale" /><AuSelect id="gallery-direction" :label="text('Direction','Direction')" :model-value="direction" :items="[{value:'ltr',title:'LTR'},{value:'rtl',title:'RTL'}]" @update:model-value="value => direction = value as 'ltr'|'rtl'" /><AuAlert tone="info">{{ text('Tous les contrôles sont locaux. Aucun service ni compte n’est nécessaire.','All controls are local. No service or account is required.') }}</AuAlert><AuFieldNote class="gallery-caption">{{ text('Cette galerie teste les composants ; elle ne calcule aucune pièce.','This gallery tests the controls; it does not calculate parts.') }}</AuFieldNote></div></template>
    <template #stage><div class="gallery-stage-top"><AuTabs v-model="tab" :label="text('Vue','View')" :items="[{value:'preview',title:text('Aperçu','Preview'),compactTitle:text('Vue','View')},{value:'details',title:text('Détails','Details'),compactTitle:text('Info','Info')},{value:'disabled',title:text('Indisponible','Unavailable'),compactTitle:'—',disabled:true},{value:'svg',title:'SVG'}]" /></div><div v-if="tab!=='svg'" class="gallery-preview"><span class="gallery-eyebrow">{{ text('APERÇU DE DÉMONSTRATION','DEMONSTRATION PREVIEW') }}</span><svg viewBox="0 0 300 270" aria-hidden="true"><defs><linearGradient id="gallery-shade" x1="0" y1="0" x2="1" y2="1"><stop :stop-color="color" offset="0" /><stop :stop-color="color" stop-opacity=".6" offset="1" /></linearGradient></defs><g stroke="#ffffff" stroke-width="2" fill="url(#gallery-shade)" :transform="`translate(${slider * .08},0)`"><path d="M150 25 245 80 245 190 150 245 55 190 55 80Z" /><path d="M55 80 150 135 245 80M150 135v110" /><path d="M79 93v111M103 106v112M127 120v112M174 121v109M198 107v111M222 94v112" /></g></svg><h2>{{ text('Pensé pour créer.','Made for creating.') }}</h2><p>{{ text('Une scène claire, des réglages lisibles et une aide à portée de main.','A clear stage, readable settings and help within reach.') }}</p><p v-if="tab === 'details'" class="gallery-escaped">{{ '<img src=x onerror=alert(1)>' }}</p></div><div v-if="tab==='svg'" class="gallery-svg-demo"><AuSvgViewport ref="viewport" :bounds="{x:0,y:0,width:120,height:80}" :locale="locale" :label="text('Contours SVG. Glissez, zoomez à la molette, 0 pour recentrer.','SVG contours. Drag, wheel to zoom, 0 to recenter.')"><path d="M0 0H120V80H0Z M56 40a4 4 0 1 0 8 0a4 4 0 1 0 -8 0Z"/></AuSvgViewport></div><div class="gallery-scene-bottom"><AuButton id="gallery-camera" @click="viewport?.fit()" icon :aria-label="text('Cadrer','Fit')"><AuIcon path="M2 6V2h4M10 2h4v4M14 10v4h-4M6 14H2v-4" /></AuButton><div class="gallery-slider"><AuSlider id="gallery-slider" v-model="slider" :label="text('Aperçu','Preview')" :help="text('Ce curseur modifie uniquement la démonstration.','This slider changes only the demonstration.')" :help-label="text('Aide : aperçu','Help: preview')" /></div></div></template>
    <template #parameters><div class="gallery-header"><span>{{ text('Composants','Components') }}</span><AuButton id="gallery-reset" @click="number = locale === 'fr' ? '0,25' : '0.25'; slider = 35; color = '#c44336'; saved = false; cancelled = false">{{ text('Réinitialiser','Reset') }}</AuButton></div><div class="gallery-rail-content"><AuCard id="gallery-inputs" :title="text('Saisie et validation','Input and validation')"><AuNumericField id="gallery-number" v-model="number" :label="text('Épaisseur','Thickness')" suffix="mm" :step=".01" :adjust="adjust" :error="numericError" :help="text('Les valeurs incomplètes restent visibles. Aucune conversion automatique vers zéro.','Incomplete values stay visible. No automatic coercion to zero.')" :help-label="text('Aide : épaisseur','Help: thickness')" /><AuSelect id="gallery-material" v-model="material" :label="text('Matériau','Material')" :items="[{value:'paper',title:text('Papier','Paper'),color:'#c44336'},{value:'wood',title:text('Contreplaqué','Plywood'),color:'#d2a773'},{value:'unavailable',title:text('Indisponible','Unavailable'),disabled:true,color:'url(https://invalid.example/paint)'}]" /><AuCheckbox id="gallery-checkbox" v-model="enabled" :label="text('Option active','Active option')" :help="text('La case est accessible au clavier et associée à son libellé.','The checkbox has an associated label and supports the keyboard.')" :help-label="text('Aide : option','Help: option')" /></AuCard><AuCard id="gallery-switches" :title="text('Options','Options')"><AuSwitch id="gallery-mirror" v-model="mirrored" :label="text('Effet miroir','Mirror')" :help="text('Reflète le motif sur la seconde aile.','Reflects the pattern on the second wing.')"/><AuSwitch id="gallery-switch-disabled" :model-value="true" :label="text('Indisponible','Unavailable')" disabled/><AuSwitch id="gallery-switch-loading" :model-value="false" :label="text('Calcul en cours','Calculating')" loading/></AuCard><AuCard id="gallery-colors" :title="text('Couleurs et matières','Colours and materials')"><AuSwatches v-model="color" :label="text('Couleur','Colour')" :items="[{value:'#c44336',color:'#c44336',title:text('Rouge','Red'),dark:true},{value:'#356aa0',color:'#356aa0',title:text('Bleu','Blue'),dark:true},{value:'#407354',color:'#407354',title:text('Vert','Green'),dark:true},{value:'#e2b742',color:'#e2b742',title:text('Jaune','Yellow')}]" /><AuColorField id="gallery-color" v-model="color" :label="text('Couleur personnalisée','Custom color')" :hex-label="text('Couleur hexadécimale (#RRGGBB)','Hex color (#RRGGBB)')" :invalid-message="text('Saisissez # suivi de six chiffres ou lettres de A à F.','Enter # followed by six digits or letters from A to F.')"/><AuHelp :label="text('Aide : matière','Help: material')" :text="text('Les apparences ne modifient pas les dimensions. Ce composant reste indépendant du métier.','Appearance does not change dimensions. This control is independent of any specific generator.')"><span>{{ text('Aide contextuelle','Contextual help') }}</span></AuHelp></AuCard><AuButton id="gallery-settings-trigger" aria-haspopup="dialog" :aria-expanded="String(settingsOpen)" @click="settingsOpen = !settingsOpen">{{ text('Réglages détaillés','Detailed settings') }}</AuButton><VMenu v-model="settingsOpen" activator="#gallery-settings-trigger" :open-on-click="false" :close-on-content-click="false" :activator-props="{ 'aria-haspopup':'dialog','aria-controls':'gallery-settings' }" location="bottom end" :offset="8" :transition="false" :z-index="3" content-class="au-overlay au-profile-compact gallery-settings-overlay"><VCard id="gallery-settings" class="gallery-settings-card" role="dialog" :aria-label="text('Réglages détaillés','Detailed settings')"><AuSelect id="gallery-overlay-select" v-model="material" :label="text('Matériau','Material')" :items="[{value:'paper',title:text('Papier','Paper'),color:'#c44336'},{value:'wood',title:text('Contreplaqué','Plywood'),color:'#d2a773'}]" :help="text('La même aide fonctionne aussi dans un menu de réglages.','The same help works inside a settings menu too.')" :help-label="text('Aide : matériau du menu','Help: menu material')" /><AuNumericField id="gallery-overlay-number" v-model="number" :label="text('Épaisseur','Thickness')" suffix="mm" :step=".01" :adjust="adjust" :error="numericError" /><AuButton id="gallery-settings-close" @click="settingsOpen = false">{{ text('Fermer','Close') }}</AuButton></VCard></VMenu><AuCard id="gallery-feedback" :title="text('État et retour utilisateur','Status and feedback')"><AuProgress v-if="!cancelled" id="gallery-progress" :label="text('Mise à jour','Updating')" :value="75" :cancel-label="text('Annuler','Cancel')" @cancel="cancelled = true" /><AuAlert v-else tone="info">{{ text('Mise à jour annulée.','Update cancelled.') }}</AuAlert><AuAlert v-if="saved" tone="success" class="gallery-success">{{ text('Action confirmée.','Action confirmed.') }}</AuAlert></AuCard><AuCard id="gallery-scrub-contract" :collapsible="false" :title="text('Glisser ou saisir','Drag or type')">
      <AuSegmentedControl id="gallery-mode" v-model="density" :label="text('Densité','Density')" :items="[{value:'spacing',title:text('Écart','Gap')},{value:'disabled',title:text('Indisponible','Unavailable'),disabled:true},{value:'count',title:text('Nombre','Count')}]" />
      <AuCheckbox id="gallery-show-scrub" v-model="showScrub" :label="text('Afficher le champ','Show the field')" />
      <AuNumericField v-if="showScrub" id="gallery-scrub" v-model="scrub" :label="text('Décimale bornée','Bounded decimal')" suffix="mm" :step=".05" :min="0" :max="10" />
      <output id="gallery-scrub-value">{{ scrub }}</output>
      <AuButton id="gallery-scrub-reset" @click="scrub = locale === 'fr' ? '2,5' : '2.5'">{{ text('Autre valeur','Another value') }}</AuButton>
      <AuNumericField id="gallery-integer" v-model="integer" :label="text('Entier','Integer')" input-mode="numeric" :step="1" :min="2" :max="100" />
      <AuNumericField id="gallery-readonly" v-model="readOnlyDraft" :label="text('Lecture seule','Read only')" read-only />
      <AuNumericField id="gallery-disabled" v-model="disabledDraft" :label="text('Désactivé','Disabled')" disabled />
      <AuNumericField id="gallery-no-drag" v-model="noDragDraft" :label="text('Saisie seulement','Typing only')" :drag="false" :step=".5" />
    </AuCard><AuButton id="gallery-action" primary block :disabled="!!numericError" @click="saved = true">{{ text('Action principale','Primary action') }}</AuButton></div></template>
  </AuLayout></AuRoot>
</template>
